advanced.code:
@Injectable()
export class SessionStore { count = 0; }

@Component({
  selector: 'feature-shell',
  providers: [SessionStore],
  template: ''
})
export class FeatureShell {}

constructor(private zone: NgZone) {}
ngOnInit() {
  this.zone.runOutsideAngular(() => {
    fromEvent(window, 'scroll').pipe(auditTime(16)).subscribe(() => {
      const y = window.scrollY;
      this.zone.run(() => this.scrollY.set(y));
    });
  });
}

private users$?: Observable<User[]>;
getUsers() {
  if (!this.users$) {
    this.users$ = this.http.get<User[]>('/api/users').pipe(
      shareReplay({ bufferSize: 1, refCount: true })
    );
  }
  return this.users$;
}

// bad: new observable each check
get user$() { return this.http.get<User>('/api/user'); }

// better: create once
user$ = this.http.get<User>('/api/user');
